import { expect, test } from 'bun:test';
import { mkdtempSync, readFileSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { importDataset } from './import-under-review.ts';
import { canonical, sha256 } from '../../../scripts/datasets/store.ts';

const iri = (n: number) => `https://rezics.com/id/00000000-0000-4000-8000-${String(n).padStart(12, '0')}`;
function sourceRecord(id: string, native: 'work' | 'character') {
  return { key: `vndb:${native === 'work' ? 'vn' : 'character'}:${id}`, provider: 'vndb' as const,
    kind: native === 'work' ? 'vn' : 'character', externalId: id, title: id, language: 'ja',
    sourceUrl: `https://vndb.org/${id}`, native, data: { captured: true } };
}
async function selectedReplay() {
  const directory = mkdtempSync(resolve('.temp/review/retained-importer/fixture-'));
  const outside = sourceRecord('v99', 'work'), work = sourceRecord('v11', 'work'), character = sourceRecord('c1', 'character');
  const appearance = { from: character.key, to: work.key, kind: 'appearance', data: { order: 1 } };
  const edges = [{ from: work.key, to: character.key, kind: 'character', data: { order: 0 } },
    appearance, structuredClone(appearance), { from: character.key, to: outside.key, kind: 'appearance', data: { order: 2 } }];
  const snapshot = { format: 'rezics-local-dataset-v1' as const, id: 'parent-intake-fixture', digest: 'a'.repeat(64),
    createdAt: '2026-10-19T00:00:00Z', sources: [{ provider: 'vndb' as const, roots: [outside.key, work.key],
      records: [outside, character, work], edges, images: [], scope: { complete: true } }], images: [], captures: [] };
  const frozen = JSON.stringify(snapshot);
  mkdirSync(join(directory, 'snapshots', snapshot.id), { recursive: true });
  writeFileSync(join(directory, 'snapshots', snapshot.id, 'snapshot.json'), frozen);
  const requests: { path: string; key?: string; body: unknown }[] = [];
  let serial = 1;
  const replies = new Map<string, Record<string, unknown>>();
  const sourceRecords = new Map<string, string>();
  const api = { async request(method: string, path: string, body?: unknown, key?: string) {
    requests.push(structuredClone({ path, key, body }));
    if (method === 'POST' && path === '/v1/catalogue/candidates')
      return { status: 200, body: { sourcePosition: { dataEpoch: 'unit-fixture-epoch' } } };
    if (method !== 'POST' || path !== '/v1/sources/intakes' || !key) throw new Error(`Unexpected fixture request ${method} ${path}`);
    const saved = replies.get(key);
    if (saved) return { status: 200, body: { ...structuredClone(saved), replayed: true } };
    const input = body as Record<string, unknown>, bytes = Buffer.from(String(input.rawBytesBase64), 'base64');
    const identity = canonical([input.provider, input.namespace, input.externalId]);
    let sourceRecordId = sourceRecords.get(identity);
    if (!sourceRecordId) { sourceRecordId = iri(serial++); sourceRecords.set(identity, sourceRecordId); }
    const result = { replayed: false, observation: { ...input, record: sourceRecordId, observation: iri(serial++),
      byteDigest: sha256(bytes), byteLength: bytes.length, state: 'staged', submittedAt: '2026-10-19T00:00:00Z' } };
    replies.set(key, structuredClone(result));
    return { status: 201, body: result };
  } };
  const options = { api, mainOrigin: 'http://127.0.0.1:1', webOrigin: 'http://127.0.0.1:2', actingSubject: iri(999), native: false };
  try {
    const previous = await importDataset(directory, snapshot, options);
    const old = JSON.parse(readFileSync(previous.intakeReceiptsFile, 'utf8'));
    const before = requests.length;
    const selected = await importDataset(directory, snapshot, { ...options, maxRecords: 0, selection: { roots: [work.key],
      relatedWorkDepth: 0, budget: { maxInputItems: 100, maxRecords: 20, maxEdges: 20, maxImages: 20,
        maxJsonBytes: 1_000_000, maxMediaBytes: 1_000_000 } } });
    const current = JSON.parse(readFileSync(selected.intakeReceiptsFile, 'utf8'));
    expect(selected.records).toBe(2);
    expect(selected.selection!.sources[0]!.edges).toEqual([0, 1, 2]);
    expect(readFileSync(join(directory, 'snapshots', snapshot.id, 'snapshot.json'), 'utf8')).toBe(frozen);
    return { old: old.records[character.key], current: current.records[character.key],
      parentEdges: edges.filter(edge => edge.from === character.key), requests: requests.slice(before) };
  } finally { rmSync(directory, { recursive: true, force: true }); }
}

test('selected native view retains the original complete parent intake envelope', async () => {
  const result = await selectedReplay();
  expect(result.old.envelope.edges).toEqual(result.parentEdges);
  // Outcome: selecting the native view cannot discard captured source adjacency.
  expect(result.current.envelope.edges).toEqual(result.parentEdges);
});

test('selection reuses the original source intake command and acknowledgement', async () => {
  const result = await selectedReplay();
  const previous = result.old.intakes[0], current = result.current.intakes[0];
  expect(previous.command.request.rawBytesBase64).toBe(Buffer.from(canonical(result.old.envelope)).toString('base64'));
  // Outcome: the same frozen source observation keeps its original request key.
  expect(current.command.key).toBe(previous.command.key);
  expect(current.command.request).toEqual(previous.command.request);
  expect(current.command.result).toEqual(previous.command.result);
  expect(result.requests.filter(request => request.path === '/v1/sources/intakes')).toEqual([]);
});
